mapper.select:
select sf.customer as customer,sf.person_name as person_name,sf.subbarcode as subbarcode,sf.gender as gender,sf.cancertype as cancertype,sf.pathologicaltype as pathologicaltype,
sf.age as age,var.ori_variant as ori_variant,var.report_id as report_id,sf.loaded_date as loaded_date,sf.specimen_type as specimen_type from (
select report_id,gene,variant,ori_variant from this_genetic_marker_vw2 where gene=#{gene} and variant=#{variant}
union select report_id,gene,variant,ori_variant from cr_evw where gene=#{gene} and variant=#{variant}
) var
join analysis_report ar on ar.report_id = var.report_id 
join sample_file sf on sf.subbarcode = ar.subbarcode
where ar.status ="报告发送成功"

	and sf.loaded_date > #{before_date}


	and sf.loaded_date < #{after_date}


	and ar.primary_cancer_id = #{primary_cancer_id}

select sf.customer as customer,sf.person_name as person_name,sf.subbarcode as subbarcode,sf.gender as gender,sf.cancertype as cancertype,sf.pathologicaltype as pathologicaltype,
sf.age as age,var.ori_variant as ori_variant,var.report_id as report_id,sf.loaded_date as loaded_date  from (
select report_id,gene,variant,ori_variant from this_genetic_marker_vw2 where mut_type="融合" and (gene=#{gene} or ori_variant LIKE concat(#{gene},'-%'))
) var
join analysis_report ar on ar.report_id = var.report_id 
join sample_file sf on sf.subbarcode = ar.subbarcode
where ar.status = "报告发送成功"

	and sf.loaded_date > #{before_date}


	and sf.loaded_date < #{after_date}


	and ar.primary_cancer_id = #{primary_cancer_id}
